-- Hand-written: P7 LUT fold: the one letter of undertaking of M3 (tax.lut) folded into the list under the M5.2 rule and its key removed, and the two LUT triggers created again from the list-only rule, generated by scripts/write-triggers.ts from src/triggers.ts.
UPDATE settings AS s SET value = CASE WHEN json_type(f.v, '$.luts') = 'array' THEN json_insert(f.v, '$.luts[#]', json_object('fy', f.fy, 'arn', f.arn, 'filedOn', NULL)) ELSE json_insert(f.v, '$.luts', json_array(json_object('fy', f.fy, 'arn', f.arn, 'filedOn', NULL))) END
     FROM (SELECT key, v, json_extract(v, '$.lut.fy') AS fy, upper(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(json_extract(v, '$.lut.arn'), char(9), ''), char(10), ''), char(11), ''), char(12), ''), char(13), ''), char(32), ''), char(160), ''), char(5760), ''), char(8192), ''), char(8193), ''), char(8194), ''), char(8195), ''), char(8196), ''), char(8197), ''), char(8198), ''), char(8199), ''), char(8200), ''), char(8201), ''), char(8202), ''), char(8232), ''), char(8233), ''), char(8239), ''), char(8287), ''), char(12288), ''), char(65279), ''), char(223), 'SS'), char(305), 'I'), char(383), 'S'), char(64256), 'FF'), char(64257), 'FI'), char(64258), 'FL'), char(64259), 'FFI'), char(64260), 'FFL'), char(64261), 'ST'), char(64262), 'ST')) AS arn
           FROM (SELECT key, CASE WHEN json_valid(value) THEN value END AS v FROM settings WHERE key = 'tax')) AS f
     WHERE s.key = f.key
       AND json_type(f.v, '$.lut.arn') = 'text'
       AND json_type(f.v, '$.lut.fy') = 'text'
       AND (json_type(f.v, '$.luts') = 'array' OR json_type(f.v, '$.luts') IS NULL)
       AND NOT EXISTS (SELECT 1 FROM json_each(f.v, '$.luts') l WHERE (CASE WHEN l.type = 'object' THEN json_extract(l.value, '$.fy') END) = f.fy)
       AND length(f.fy) = 4 AND length(CAST(f.fy AS BLOB)) = 4 AND f.fy NOT GLOB '*[^0-9]*'
       AND (CAST(substr(f.fy, 1, 2) AS INTEGER) + 1) % 100 = CAST(substr(f.fy, 3, 2) AS INTEGER)
       AND length(f.arn) BETWEEN 1 AND 30 AND length(CAST(f.arn AS BLOB)) = length(f.arn) AND f.arn NOT GLOB '*[^A-Z0-9]*'
       AND coalesce(json_array_length(f.v, '$.luts'), 0) < 20;
--> statement-breakpoint
UPDATE settings SET value = json_remove(value, '$.lut'), version = version + 1 WHERE key = 'tax' AND json_type(CASE WHEN json_valid(value) THEN value END, '$.lut') IS NOT NULL;
--> statement-breakpoint
DROP TRIGGER `documents_advance_lut_fy`;
--> statement-breakpoint
CREATE TRIGGER `documents_advance_lut_fy` BEFORE UPDATE OF status ON `documents` WHEN OLD.status = 'draft' AND NEW.status = 'issued' AND NEW.type = 'export_invoice' AND NEW.export_mode = 'lut' AND json_extract(NEW.header_extras, '$.advance.receivedOn') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM settings ts WHERE ts.key = 'tax' AND
           EXISTS (SELECT 1 FROM json_each(ts.value, '$.luts') l WHERE json_extract(l.value, '$.fy') = (CASE WHEN CAST(substr(json_extract(NEW.header_extras, '$.advance.receivedOn'), 6, 2) AS INTEGER) >= 4 THEN substr(json_extract(NEW.header_extras, '$.advance.receivedOn'), 3, 2) || printf('%02d', (CAST(substr(json_extract(NEW.header_extras, '$.advance.receivedOn'), 3, 2) AS INTEGER) + 1) % 100) ELSE printf('%02d', (CAST(substr(json_extract(NEW.header_extras, '$.advance.receivedOn'), 3, 2) AS INTEGER) + 99) % 100) || substr(json_extract(NEW.header_extras, '$.advance.receivedOn'), 3, 2) END) AND trim(coalesce(json_extract(l.value, '$.arn'), '')) <> '')) BEGIN SELECT RAISE(ABORT, 'documents_advance_lut_fy: an export invoice under LUT for a payment received needs a LUT saved for the financial year of the day the payment arrived'); END;
